arguments.command:
cd /app; cp releases/1.6.0/herbarium.sqlite /tmp/u.sqlite; python3 tools/stratum.py upgrade /tmp/u.sqlite | tail -5; python3 - <<'E'
import sqlite3
a=sqlite3.connect('build/herbarium.sqlite');b=sqlite3.connect('/tmp/u.sqlite')
def sch(c):return {(r[0],r[1]) :r[2] for r in c.execute("select type,name,sql from sqlite_master where name!='schema_migrations'")}
sa,sb=sch(a),sch(b)
for k in set(sa)|set(sb):
    if sa.get(k)!=sb.get(k):print(k,'\n',sa.get(k),'\n',sb.get(k))
for t,o in[('site','code'),('collector','1'),('taxon','1'),('specimen','1')]:
    q=f"select * from {t} order by {o}"
    ra,rb=a.execute(q).fetchall(),b.execute(q).fetchall()
    print(t,len(ra),len(rb),ra==rb)
    if ra!=rb:
        print([ (x,y) for x,y in zip(ra,rb) if x!=y][:5])
E

